104		enc.AppendString(filenameFromPath(caller.TrimmedPath()))
105	}
106	
107	func filenameFromPath(path string) string {
108		for i := len(path) - 1; i >= 0; i-- {
109			if path[i] == '/' {
110				return path[i+1:]
111			}
112		}
113		return path
