131	//	SR_LOG_ENCODING    (json|console) default: json
132	//	SR_LOG_DEVELOPMENT (true|false) default: false
133	//	SR_LOG_ADD_CALLER  (true|false) default: true
134	func InitLoggerFromEnv() (*zap.Logger, error) {
135		cfg := Config{
136			Level:       getenvDefault("SR_LOG_LEVEL", "info"),
137			Encoding:    getenvDefault("SR_LOG_ENCODING", "json"),
138			Development: parseBool(getenvDefault("SR_LOG_DEVELOPMENT", "false")),
139			AddCaller:   parseBool(getenvDefault("SR_LOG_ADD_CALLER", "true")),
