package logging

import (
	"os"
	"strings"

	"go.uber.org/zap"
	"go.uber.org/zap/zapcore"
)

// componentKey is the structured field name for the component identifier.
const componentKey = "component"

// Config holds logger configuration.
type Config struct {
	// Level is one of: debug, info, warn, error, dpanic, panic, fatal
	Level string
	// Encoding is one of: json, console
	Encoding string
	// Development enables dev-friendly logging (stacktraces on error, etc.)
	Development bool
	// AddCaller enables caller annotations.
	AddCaller bool
}

// InitLogger initializes a global zap logger using the provided config.
// It also redirects the standard library logger to zap and returns the logger.
func InitLogger(cfg Config) (*zap.Logger, error) {
	zcfg := buildZapConfig(cfg)
	configureEncoder(&zcfg.EncoderConfig)

	logger, err := buildLogger(zcfg, cfg.AddCaller)
	if err != nil {
		return nil, err
	}

	// Replace globals and redirect stdlib log
	zap.ReplaceGlobals(logger)
	_ = zap.RedirectStdLog(logger)

	return logger, nil
}

func buildZapConfig(cfg Config) zap.Config {
	enc := normalizeLogValue(cfg.Encoding)
	if cfg.Development {
		zcfg := zap.NewDevelopmentConfig()
		if enc != "" {
			zcfg.Encoding = enc
		}
		return zcfg
	}

	zcfg := zap.NewProductionConfig()
	zcfg.Level = zap.NewAtomicLevelAt(resolveLogLevel(cfg.Level))
	zcfg.Encoding = resolveLogEncoding(enc)
	return zcfg
}

func resolveLogLevel(level string) zapcore.Level {
	switch normalizeLogValue(level) {
	case "", "info":
		return zapcore.InfoLevel
	case "debug":
		return zapcore.DebugLevel
	case "warn", "warning":
		return zapcore.WarnLevel
	case "error":
		return zapcore.ErrorLevel
	case "dpanic":
		return zapcore.DPanicLevel
	case "panic":
		return zapcore.PanicLevel
	case "fatal":
		return zapcore.FatalLevel
	default:
		return zapcore.InfoLevel
	}
}

func resolveLogEncoding(enc string) string {
	if enc == "console" {
		return "console"
	}
	return "json"
}

func normalizeLogValue(value string) string {
	return strings.ToLower(strings.TrimSpace(value))
}

func configureEncoder(cfg *zapcore.EncoderConfig) {
	cfg.TimeKey = "ts"
	// ISO 8601 with millisecond precision
	cfg.EncodeTime = zapcore.TimeEncoderOfLayout("2006-01-02T15:04:05.000")
	cfg.MessageKey = "msg"
	cfg.LevelKey = "level"
	cfg.EncodeLevel = zapcore.LowercaseLevelEncoder
	cfg.CallerKey = "caller"
	cfg.EncodeCaller = encodeCallerFilenameOnly
}

func encodeCallerFilenameOnly(caller zapcore.EntryCaller, enc zapcore.PrimitiveArrayEncoder) {
	enc.AppendString(filenameFromPath(caller.TrimmedPath()))
}

func filenameFromPath(path string) string {
	for i := len(path) - 1; i >= 0; i-- {
		if path[i] == '/' {
			return path[i+1:]
		}
	}
	return path
}

func buildLogger(zcfg zap.Config, addCaller bool) (*zap.Logger, error) {
	logger, err := zcfg.Build()
	if err != nil {
		return nil, err
	}
	if addCaller {
		logger = logger.WithOptions(zap.AddCaller(), zap.AddCallerSkip(1))
	}
	return logger, nil
}

// InitLoggerFromEnv builds a logger from environment variables and initializes it.
// Supported env vars:
//
//	SR_LOG_LEVEL       (debug|info|warn|error|dpanic|panic|fatal) default: info
//	SR_LOG_ENCODING    (json|console) default: json
//	SR_LOG_DEVELOPMENT (true|false) default: false
//	SR_LOG_ADD_CALLER  (true|false) default: true
func InitLoggerFromEnv() (*zap.Logger, error) {
	cfg := Config{
		Level:       getenvDefault("SR_LOG_LEVEL", "info"),
		Encoding:    getenvDefault("SR_LOG_ENCODING", "json"),
		Development: parseBool(getenvDefault("SR_LOG_DEVELOPMENT", "false")),
		AddCaller:   parseBool(getenvDefault("SR_LOG_ADD_CALLER", "true")),
	}
	return InitLogger(cfg)
}

func getenvDefault(k, d string) string {
	v := os.Getenv(k)
	if v == "" {
		return d
	}
	return v
}

func parseBool(s string) bool {
	s = strings.TrimSpace(strings.ToLower(s))
	return s == "1" || s == "true" || s == "yes" || s == "on"
}

// LogEvent emits a structured log at info level with a standard envelope.
// Fields provided by callers take precedence and will not be overwritten.
func LogEvent(event string, fields map[string]interface{}) {
	logEventAt(zapcore.InfoLevel, event, fields)
}

// DebugEvent emits a structured log at debug level.
func DebugEvent(event string, fields map[string]interface{}) {
	logEventAt(zapcore.DebugLevel, event, fields)
}

// WarnEvent emits a structured log at warn level.
func WarnEvent(event string, fields map[string]interface{}) {
	logEventAt(zapcore.WarnLevel, event, fields)
}

// ErrorEvent emits a structured log at error level.
func ErrorEvent(event string, fields map[string]interface{}) {
	logEventAt(zapcore.ErrorLevel, event, fields)
}

func logEventAt(level zapcore.Level, event string, fields map[string]interface{}) {
	prepared := prepareEventFields(event, fields)
	zfields := make([]zap.Field, 0, len(prepared))
	for k, v := range prepared {
		zfields = append(zfields, zap.Any(k, v))
	}

	logger := zap.L().With(zfields...)
	switch level {
	case zapcore.DebugLevel:
		logger.Debug(event)
	case zapcore.WarnLevel:
		logger.Warn(event)
	case zapcore.ErrorLevel:
		logger.Error(event)
	case zapcore.FatalLevel:
		logger.Fatal(event)
	default:
		logger.Info(event)
	}
}

func prepareEventFields(event string, fields map[string]interface{}) map[string]interface{} {
	prepared := make(map[string]interface{}, len(fields)+1)
	for k, v := range fields {
		prepared[k] = v
	}
	if _, ok := prepared["event"]; !ok {
		prepared["event"] = event
	}
	return prepared
}

// Helper printf-style wrappers to ease migration from log.Printf.
func Infof(format string, args ...interface{})  { zap.S().Infof(format, args...) }
func Warnf(format string, args ...interface{})  { zap.S().Warnf(format, args...) }
func Errorf(format string, args ...interface{}) { zap.S().Errorf(format, args...) }
func Debugf(format string, args ...interface{}) { zap.S().Debugf(format, args...) }
func Fatalf(format string, args ...interface{}) { zap.S().Fatalf(format, args...) }

// DebugEnabled reports whether the global logger emits at debug level. Callers
// use it to skip building expensive debug-only payloads (e.g. cloning and
// redacting a protobuf message) when debug logging is disabled.
func DebugEnabled() bool { return zap.L().Core().Enabled(zapcore.DebugLevel) }

// WithComponent returns a named sub-logger that carries a "component" field
// in every log line, making it trivial to filter by subsystem.
//
// Usage:
//
//	log := logging.WithComponent("extproc")
//	log.Infof("request received")   // {"component":"extproc","level":"info",...}
func WithComponent(name string) *zap.SugaredLogger {
	return zap.L().With(zap.String(componentKey, name)).Sugar()
}

// ComponentEvent is like LogEvent but includes the "component" field.
func ComponentEvent(component, event string, fields map[string]interface{}) {
	logComponentEventAt(zapcore.InfoLevel, component, event, fields)
}

// ComponentDebugEvent is like DebugEvent but includes the "component" field.
func ComponentDebugEvent(component, event string, fields map[string]interface{}) {
	logComponentEventAt(zapcore.DebugLevel, component, event, fields)
}

// ComponentWarnEvent is like WarnEvent but includes the "component" field.
func ComponentWarnEvent(component, event string, fields map[string]interface{}) {
	logComponentEventAt(zapcore.WarnLevel, component, event, fields)
}

// ComponentErrorEvent is like ErrorEvent but includes the "component" field.
func ComponentErrorEvent(component, event string, fields map[string]interface{}) {
	logComponentEventAt(zapcore.ErrorLevel, component, event, fields)
}

// ComponentFatalEvent is like FatalEvent but includes the "component" field.
func ComponentFatalEvent(component, event string, fields map[string]interface{}) {
	logComponentEventAt(zapcore.FatalLevel, component, event, fields)
}

func logComponentEventAt(level zapcore.Level, component, event string, fields map[string]interface{}) {
	prepared := prepareEventFields(event, fields)
	if _, ok := prepared[componentKey]; !ok {
		prepared[componentKey] = component
	}
	logEventAt(level, event, prepared)
}

package tracing

import (
	"context"
	"fmt"
	"strings"
	"time"

	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/exporters/otlp/otlptrace/otlptracegrpc"
	"go.opentelemetry.io/otel/exporters/stdout/stdouttrace"
	"go.opentelemetry.io/otel/propagation"
	"go.opentelemetry.io/otel/sdk/resource"
	sdktrace "go.opentelemetry.io/otel/sdk/trace"
	semconv "go.opentelemetry.io/otel/semconv/v1.4.0"
	"go.opentelemetry.io/otel/trace"
	"google.golang.org/grpc/credentials/insecure"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
)

// TracingConfig holds the tracing configuration
type TracingConfig struct {
	Enabled               bool
	Provider              string
	ExporterType          string
	ExporterEndpoint      string
	ExporterInsecure      bool
	SamplingType          string
	SamplingRate          float64
	ServiceName           string
	ServiceVersion        string
	DeploymentEnvironment string
}

var (
	tracerProvider *sdktrace.TracerProvider
	tracer         trace.Tracer
)

// InitTracing initializes the OpenTelemetry tracing provider
func InitTracing(ctx context.Context, cfg TracingConfig) error {
	if !cfg.Enabled {
		return nil
	}

	// Create resource with service information
	res, err := resource.New(ctx,
		resource.WithAttributes(
			semconv.ServiceNameKey.String(cfg.ServiceName),
			semconv.ServiceVersionKey.String(cfg.ServiceVersion),
			semconv.DeploymentEnvironmentKey.String(cfg.DeploymentEnvironment),
		),
	)
	if err != nil {
		return fmt.Errorf("failed to create resource: %w", err)
	}

	// Create exporter based on configuration
	var exporter sdktrace.SpanExporter
	switch cfg.ExporterType {
	case "otlp":
		exporter, err = createOTLPExporter(ctx, cfg)
		if err != nil {
			return fmt.Errorf("failed to create OTLP exporter: %w", err)
		}
	case "stdout":
		exporter, err = stdouttrace.New(
			stdouttrace.WithPrettyPrint(),
		)
		if err != nil {
			return fmt.Errorf("failed to create stdout exporter: %w", err)
		}
	default:
		return fmt.Errorf("unsupported exporter type: %s", cfg.ExporterType)
	}

	sampler := samplerFromConfig(cfg)

	// Create tracer provider
	tracerProvider = sdktrace.NewTracerProvider(
		sdktrace.WithResource(res),
		sdktrace.WithBatcher(exporter),
		sdktrace.WithSampler(sampler),
	)

	// Set global tracer provider
	otel.SetTracerProvider(tracerProvider)

	// Set global propagator for trace context propagation
	otel.SetTextMapPropagator(propagation.NewCompositeTextMapPropagator(
		propagation.TraceContext{},
		propagation.Baggage{},
	))

	// Create named tracer for the router
	tracer = tracerProvider.Tracer("semantic-router")

	return nil
}

func samplerFromConfig(cfg TracingConfig) sdktrace.Sampler {
	switch samplingType := strings.ToLower(strings.TrimSpace(cfg.SamplingType)); samplingType {
	case "always_on":
		return sdktrace.AlwaysSample()
	case "always_off":
		return sdktrace.NeverSample()
	case "probabilistic", "traceidratio", "trace_id_ratio":
		return sdktrace.TraceIDRatioBased(cfg.SamplingRate)
	case "":
		return sdktrace.AlwaysSample()
	default:
		logging.ComponentWarnEvent("tracing", "tracing_sampling_type_unknown", map[string]interface{}{
			"sampling_type": cfg.SamplingType,
			"fallback":      "always_on",
		})
		return sdktrace.AlwaysSample()
	}
}

// createOTLPExporter creates an OTLP gRPC exporter
func createOTLPExporter(ctx context.Context, cfg TracingConfig) (sdktrace.SpanExporter, error) {
	opts := []otlptracegrpc.Option{
		otlptracegrpc.WithEndpoint(cfg.ExporterEndpoint),
	}

	if cfg.ExporterInsecure {
		opts = append(opts, otlptracegrpc.WithTLSCredentials(insecure.NewCredentials()))
	}

	// Create exporter with timeout context for initialization
	// Note: We don't use WithBlock() to allow the exporter to connect asynchronously
	// This prevents blocking on startup if the collector is temporarily unavailable
	ctxWithTimeout, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()

	return otlptracegrpc.New(ctxWithTimeout, opts...)
}

// ShutdownTracing gracefully shuts down the tracing provider
func ShutdownTracing(ctx context.Context) error {
	if tracerProvider != nil {
		return tracerProvider.Shutdown(ctx)
	}
	return nil
}

// GetTracer returns the global tracer instance
func GetTracer() trace.Tracer {
	if tracer == nil {
		// Return noop tracer if tracing is not initialized
		return otel.Tracer("semantic-router")
	}
	return tracer
}

// StartSpan starts a new span with the given name and options
func StartSpan(ctx context.Context, spanName string, opts ...trace.SpanStartOption) (context.Context, trace.Span) {
	// Handle nil context by using background context
	if ctx == nil {
		ctx = context.Background()
	}

	if tracer == nil {
		// Return noop tracer if tracing is not initialized
		return otel.Tracer("semantic-router").Start(ctx, spanName, opts...)
	}
	return tracer.Start(ctx, spanName, opts...)
}

// SetSpanAttributes sets attributes on a span if it exists
func SetSpanAttributes(span trace.Span, attrs ...attribute.KeyValue) {
	if span != nil {
		span.SetAttributes(attrs...)
	}
}

// RecordError records an error on a span if it exists
func RecordError(span trace.Span, err error) {
	if span != nil && err != nil {
		span.RecordError(err)
	}
}

// StartSignalSpan starts a new span for signal evaluation
// signalType: the type of signal (e.g., "keyword", "embedding", "domain")
// Returns the new context and span
func StartSignalSpan(ctx context.Context, signalType string) (context.Context, trace.Span) {
	// Use specific signal span name based on type
	var spanName string
	switch signalType {
	case "keyword":
		spanName = SpanSignalKeyword
	case "embedding":
		spanName = SpanSignalEmbedding
	case "domain":
		spanName = SpanSignalDomain
	case "fact_check":
		spanName = SpanSignalFactCheck
	case "user_feedback":
		spanName = SpanSignalUserFeedback
	case "reask":
		spanName = SpanSignalReask
	case "preference":
		spanName = SpanSignalPreference
	case "language":
		spanName = SpanSignalLanguage
	case "latency":
		spanName = SpanSignalLatency
	default:
		spanName = SpanSignalEvaluation
	}

	spanCtx, span := StartSpan(ctx, spanName)
	SetSpanAttributes(span, attribute.String(AttrSignalType, signalType))
	return spanCtx, span
}

// EndSignalSpan ends a signal span with matched rules and confidence
func EndSignalSpan(span trace.Span, matchedRules []string, confidence float64, latencyMs int64) {
	if span == nil {
		return
	}

	if len(matchedRules) > 0 {
		SetSpanAttributes(span,
			attribute.StringSlice(AttrSignalMatchedRules, matchedRules),
			attribute.Float64(AttrSignalConfidence, confidence),
			attribute.Int64(AttrSignalLatencyMs, latencyMs))
	} else {
		SetSpanAttributes(span,
			attribute.Int64(AttrSignalLatencyMs, latencyMs))
	}

	span.End()
}

// StartDecisionSpan starts a new span for decision evaluation
// decisionName: the name of the decision being evaluated
// Returns the new context and span
func StartDecisionSpan(ctx context.Context, decisionName string) (context.Context, trace.Span) {
	spanCtx, span := StartSpan(ctx, SpanDecisionEvaluation)
	SetSpanAttributes(span, attribute.String(AttrDecisionName, decisionName))
	return spanCtx, span
}

// EndDecisionSpan ends a decision span with evaluation results
func EndDecisionSpan(span trace.Span, confidence float64, matchedRules []string, strategy string) {
	if span == nil {
		return
	}

	SetSpanAttributes(span,
		attribute.Float64(AttrDecisionConfidence, confidence),
		attribute.StringSlice(AttrDecisionMatchedRules, matchedRules),
		attribute.String(AttrDecisionStrategy, strategy))

	span.End()
}

// StartPluginSpan starts a new span for plugin execution with standard attributes
// pluginType: the type of plugin (e.g., "pii", "jailbreak", "system_prompt", "semantic-cache")
// decisionName: the decision name this plugin is associated with
// Returns the new context and span
func StartPluginSpan(ctx context.Context, pluginType string, decisionName string) (context.Context, trace.Span) {
	spanCtx, span := StartSpan(ctx, SpanPluginExecution)

	// Set standard plugin attributes
	SetSpanAttributes(span,
		attribute.String(AttrPluginType, pluginType),
		attribute.String(AttrPluginDecision, decisionName))

	return spanCtx, span
}

// EndPluginSpan ends a plugin span with status and latency
// status: "success", "error", "blocked", "skipped", etc.
// latencyMs: execution time in milliseconds
// result: optional result string (e.g., "pii_detected", "jailbreak_blocked", "cache_hit")
func EndPluginSpan(span trace.Span, status string, latencyMs int64, result string) {
	if span == nil {
		return
	}

	attrs := []attribute.KeyValue{
		attribute.String(AttrPluginStatus, status),
		attribute.Int64(AttrPluginLatency, latencyMs),
	}

	if result != "" {
		attrs = append(attrs, attribute.String(AttrPluginResult, result))
	}

	SetSpanAttributes(span, attrs...)
	span.End()
}

