237	func initializeWindowedMetricsIfEnabled(cfg *config.RouterConfig) {
238		if !cfg.Observability.Metrics.WindowedMetrics.Enabled {
239			return
240		}
241	
242		if err := metrics.InitializeWindowedMetrics(cfg.Observability.Metrics.WindowedMetrics); err != nil {
243			logging.ComponentWarnEvent("router", "windowed_metrics_init_failed", map[string]interface{}{
244				"error": err.Error(),
245			})
246			return
247		}
248		logging.ComponentEvent("router", "windowed_metrics_initialized", map[string]interface{}{
249			"mode": "load_balancing",
250		})
251	}
252	
253	func registerSignalHandler(shutdownHooks *[]func()) {
254		sigChan := make(chan os.Signal, 1)
255		signal.Notify(sigChan, os.Interrupt, syscall.SIGTERM)
256	
257		go func() {
258			sig := <-sigChan
259			logging.ComponentEvent("router", "shutdown_signal_received", map[string]interface{}{
260				"signal": sig.String(),
261			})
262			for _, hook := range *shutdownHooks {
263				hook()
264			}
265			shutdownTracing()
266			os.Exit(0)
267		}()
268	}
