package main

import (
	"context"
	"flag"
	"fmt"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/prometheus/client_golang/prometheus/promhttp"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/apiserver"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/extproc"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/modelruntime"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/metrics"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/tracing"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/routerruntime"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/startupstatus"
)

type runtimeOptions struct {
	configPath             string
	certPath               string
	kubeconfig             string
	namespace              string
	port                   int
	apiPort                int
	apiBind                string
	managementAuthMode     string
	managementRemoteExpose *bool
	metricsPort            int
	enableAPI              bool
	secure                 bool
	downloadOnly           bool
}

func parseRuntimeOptions() runtimeOptions {
	var (
		configPath             = flag.String("config", "config/config.yaml", "Path to the configuration file")
		port                   = flag.Int("port", 50051, "Port to listen on for gRPC ExtProc")
		apiPort                = flag.Int("api-port", 8080, "Port to listen on for the router apiserver")
		apiBind                = flag.String("api-bind", "", "Bind address for the router apiserver (default from config: 127.0.0.1)")
		managementAuthMode     = flag.String("management-auth-mode", "", "Management API auth mode: bearer or disabled")
		managementRemoteExpose = flag.Bool("management-remote-exposure", false, "Allow remote exposure of the management API (requires bearer auth tokens in config)")
		metricsPort            = flag.Int("metrics-port", 9190, "Port for Prometheus metrics")
		enableAPI              = flag.Bool("enable-api", true, "Enable the router apiserver")
		secure                 = flag.Bool("secure", false, "Enable secure gRPC server with TLS")
		certPath               = flag.String("cert-path", "", "Path to TLS certificate directory (containing tls.crt and tls.key)")
		kubeconfig             = flag.String("kubeconfig", "", "Path to kubeconfig file (optional, uses in-cluster config if not specified)")
		namespace              = flag.String("namespace", "default", "Kubernetes namespace to watch for CRDs")
		downloadOnly           = flag.Bool("download-only", false, "Download required models and exit (useful for CI/testing)")
	)
	flag.Parse()

	return runtimeOptions{
		configPath:             *configPath,
		certPath:               *certPath,
		kubeconfig:             *kubeconfig,
		namespace:              *namespace,
		port:                   *port,
		apiPort:                *apiPort,
		apiBind:                *apiBind,
		managementAuthMode:     *managementAuthMode,
		managementRemoteExpose: boolFlagOverride(flag.CommandLine, "management-remote-exposure", *managementRemoteExpose),
		metricsPort:            *metricsPort,
		enableAPI:              *enableAPI,
		secure:                 *secure,
		downloadOnly:           *downloadOnly,
	}
}

// boolFlagOverride returns a pointer to value only when the named flag was
// explicitly supplied on the command line. Otherwise nil so config defaults
// are preserved (e.g. management_api.remote_exposure: true).
func boolFlagOverride(fs *flag.FlagSet, name string, value bool) *bool {
	set := false
	fs.Visit(func(f *flag.Flag) {
		if f.Name == name {
			set = true
		}
	})
	if !set {
		return nil
	}
	return &value
}

func initializeRuntimeLogger() {
	if _, err := logging.InitLoggerFromEnv(); err != nil {
		fmt.Fprintf(os.Stderr, "failed to initialize logger: %v\n", err)
	}
}

func loadRuntimeConfigOrFatal(configPath string) *config.RouterConfig {
	if _, err := os.Stat(configPath); os.IsNotExist(err) {
		logging.ComponentFatalEvent("router", "runtime_config_missing", map[string]interface{}{
			"config_path": configPath,
		})
	}

	cfg, err := config.Parse(configPath)
	if err != nil {
		logging.ComponentFatalEvent("router", "runtime_config_load_failed", map[string]interface{}{
			"config_path": configPath,
			"error":       err.Error(),
		})
	}
	logging.ComponentDebugEvent("router", "runtime_config_loaded", map[string]interface{}{
		"config_path":    configPath,
		"config_source":  cfg.ConfigSource,
		"decision_count": len(cfg.Decisions),
	})
	return cfg
}

func newStartupWriter(cfg *config.RouterConfig, configPath string) startupstatus.StatusWriter {
	writer := buildStartupWriter(cfg, configPath)
	writeStartupState(writer, startupstatus.State{
		Phase:   "starting",
		Ready:   false,
		Message: "Router process booting...",
	}, "Failed to write initial startup status")
	return writer
}

func buildStartupWriter(cfg *config.RouterConfig, configPath string) startupstatus.StatusWriter {
	if cfg.StartupStatus.StoreBackend == "redis" && cfg.StartupStatus.Redis != nil {
		rw, err := startupstatus.NewRedisWriter(startupstatus.RedisWriterConfig{
			Address:  cfg.StartupStatus.Redis.Address,
			Password: cfg.StartupStatus.Redis.Password,
			DB:       cfg.StartupStatus.Redis.DB,
		})
		if err != nil {
			logging.ComponentWarnEvent("router", "startup_status_redis_fallback", map[string]interface{}{
				"error":    err.Error(),
				"fallback": "file",
			})
			return startupstatus.NewFileWriter(configPath)
		}
		logging.ComponentEvent("router", "startup_status_backend", map[string]interface{}{
			"backend": "redis",
			"address": cfg.StartupStatus.Redis.Address,
		})
		return rw
	}

	logging.ComponentWarnEvent("router", "startup_status_file_backend", map[string]interface{}{
		"backend": "file",
		"message": "Startup status using local file backend. Status is not shared across replicas or visible to the dashboard in containerized deployments. Set startup_status.store_backend: redis for production use.",
	})
	return startupstatus.NewFileWriter(configPath)
}

func writeStartupState(writer startupstatus.StatusWriter, state startupstatus.State, warning string) {
	if err := writer.Write(state); err != nil {
		logging.ComponentWarnEvent("router", "startup_state_write_failed", map[string]interface{}{
			"warning": warning,
			"phase":   state.Phase,
			"ready":   state.Ready,
			"error":   err.Error(),
		})
	}
}

func failStartup(writer startupstatus.StatusWriter, format string, args ...interface{}) {
	message := fmt.Sprintf(format, args...)
	_ = writer.Write(startupstatus.State{
		Phase:   "error",
		Ready:   false,
		Message: message,
	})
	logging.ComponentFatalEvent("router", "startup_failed", map[string]interface{}{
		"message": message,
	})
}

func ensureModelsDownloadedOrFatal(cfg *config.RouterConfig, writer startupstatus.StatusWriter) {
	if err := ensureModelsDownloaded(cfg, writer); err != nil {
		failStartup(writer, "Failed to ensure models are downloaded: %v", err)
	}
}

func exitIfDownloadOnly(downloadOnly bool) {
	if !downloadOnly {
		return
	}

	logging.ComponentEvent("router", "download_only_complete", map[string]interface{}{
		"mode": "download_only",
	})
	os.Exit(0)
}

func initializeTracing(cfg *config.RouterConfig) func() {
	if !cfg.Observability.Tracing.Enabled {
		return func() {}
	}

	tracingCfg := tracing.TracingConfig{
		Enabled:               cfg.Observability.Tracing.Enabled,
		Provider:              cfg.Observability.Tracing.Provider,
		ExporterType:          cfg.Observability.Tracing.Exporter.Type,
		ExporterEndpoint:      cfg.Observability.Tracing.Exporter.Endpoint,
		ExporterInsecure:      cfg.Observability.Tracing.Exporter.Insecure,
		SamplingType:          cfg.Observability.Tracing.Sampling.Type,
		SamplingRate:          cfg.Observability.Tracing.Sampling.Rate,
		ServiceName:           cfg.Observability.Tracing.Resource.ServiceName,
		ServiceVersion:        cfg.Observability.Tracing.Resource.ServiceVersion,
		DeploymentEnvironment: cfg.Observability.Tracing.Resource.DeploymentEnvironment,
	}
	if err := tracing.InitTracing(context.Background(), tracingCfg); err != nil {
		logging.ComponentWarnEvent("router", "tracing_init_failed", map[string]interface{}{
			"provider":          tracingCfg.Provider,
			"exporter_type":     tracingCfg.ExporterType,
			"exporter_endpoint": tracingCfg.ExporterEndpoint,
			"error":             err.Error(),
		})
	}
	return shutdownTracing
}

func shutdownTracing() {
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := tracing.ShutdownTracing(shutdownCtx); err != nil {
		logging.ComponentErrorEvent("router", "tracing_shutdown_failed", map[string]interface{}{
			"error": err.Error(),
		})
	}
}

func initializeWindowedMetricsIfEnabled(cfg *config.RouterConfig) {
	if !cfg.Observability.Metrics.WindowedMetrics.Enabled {
		return
	}

	if err := metrics.InitializeWindowedMetrics(cfg.Observability.Metrics.WindowedMetrics); err != nil {
		logging.ComponentWarnEvent("router", "windowed_metrics_init_failed", map[string]interface{}{
			"error": err.Error(),
		})
		return
	}
	logging.ComponentEvent("router", "windowed_metrics_initialized", map[string]interface{}{
		"mode": "load_balancing",
	})
}

func registerSignalHandler(shutdownHooks *[]func()) {
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, os.Interrupt, syscall.SIGTERM)

	go func() {
		sig := <-sigChan
		logging.ComponentEvent("router", "shutdown_signal_received", map[string]interface{}{
			"signal": sig.String(),
		})
		for _, hook := range *shutdownHooks {
			hook()
		}
		shutdownTracing()
		os.Exit(0)
	}()
}

func startMetricsServerIfEnabled(cfg *config.RouterConfig, metricsPort int) {
	metricsEnabled := true
	if cfg.Observability.Metrics.Enabled != nil {
		metricsEnabled = *cfg.Observability.Metrics.Enabled
	}
	if metricsPort <= 0 {
		metricsEnabled = false
	}
	if !metricsEnabled {
		logging.ComponentEvent("router", "metrics_server_disabled", map[string]interface{}{
			"metrics_port": metricsPort,
		})
		return
	}

	go func() {
		http.Handle("/metrics", promhttp.Handler())
		metricsAddr := fmt.Sprintf(":%d", metricsPort)
		logging.ComponentEvent("router", "metrics_server_starting", map[string]interface{}{
			"address": metricsAddr,
		})
		if err := http.ListenAndServe(metricsAddr, nil); err != nil {
			logging.ComponentErrorEvent("router", "metrics_server_failed", map[string]interface{}{
				"address": metricsAddr,
				"error":   err.Error(),
			})
		}
	}()
}

func initializeRuntimeDependencies(
	cfg *config.RouterConfig,
	writer startupstatus.StatusWriter,
	shutdownHooks *[]func(),
	runtimeRegistry *routerruntime.Registry,
) modelruntime.EmbeddingRuntimeState {
	writeStartupState(writer, startupstatus.State{
		Phase:   "initializing_models",
		Ready:   false,
		Message: "Initializing embedding models and router dependencies...",
	}, "Failed to write initialization startup status")

	embeddingState, err := modelruntime.PrepareRouterRuntime(context.Background(), cfg, modelruntime.PrepareRouterRuntimeOptions{
		Component:                  "router",
		MaxParallelism:             modelruntime.DefaultParallelism(5),
		OnEvent:                    logRuntimeLifecycleEvent,
		InitModalityClassifierFunc: extproc.InitModalityClassifier,
	})
	if err != nil {
		failStartup(writer, "Failed to initialize runtime dependencies: %v", err)
	}
	writeStartupState(writer, startupstatus.State{
		Phase:             "initializing_models",
		Ready:             false,
		Message:           "Runtime dependencies initialized. Starting router services...",
		EmbeddingProvider: startupEmbeddingProviderStatus(embeddingState),
	}, "Failed to write runtime dependency startup status")

	initializeVectorStoreIfEnabled(cfg, shutdownHooks, runtimeRegistry)
	return embeddingState
}

func startupEmbeddingProviderStatus(state modelruntime.EmbeddingRuntimeState) *startupstatus.EmbeddingProviderStatus {
	provider := state.EmbeddingProvider
	if provider == nil {
		return nil
	}
	return &startupstatus.EmbeddingProviderStatus{
		Mode:           provider.Mode,
		Backend:        provider.Backend,
		Model:          provider.Model,
		Dimension:      provider.Dimension,
		APIKeyEnv:      provider.APIKeyEnv,
		APIKeyEnvSet:   cloneBoolPtr(provider.APIKeyEnvSet),
		Healthy:        cloneBoolPtr(provider.Healthy),
		LastProbeError: provider.LastProbeError,
		LastCheckedAt:  provider.LastCheckedAt,
	}
}

func cloneBoolPtr(value *bool) *bool {
	if value == nil {
		return nil
	}
	clone := *value
	return &clone
}

func logRuntimeLifecycleEvent(event modelruntime.Event) {
	if event.Status != modelruntime.TaskFailed && event.Status != modelruntime.TaskSkipped {
		return
	}
	payload := map[string]interface{}{
		"task":        event.Task,
		"best_effort": event.BestEffort,
	}
	if event.Error != nil {
		payload["error"] = event.Error.Error()
	}
	if event.Status == modelruntime.TaskSkipped {
		logging.ComponentWarnEvent("router", "runtime_lifecycle_task_skipped", payload)
		return
	}
	if event.BestEffort {
		logging.ComponentWarnEvent("router", "runtime_lifecycle_task_failed", payload)
		return
	}
	logging.ComponentErrorEvent("router", "runtime_lifecycle_task_failed", payload)
}

func initializeVectorStoreIfEnabled(
	cfg *config.RouterConfig,
	shutdownHooks *[]func(),
	runtimeRegistry *routerruntime.Registry,
) {
	if cfg.VectorStore == nil || !cfg.VectorStore.Enabled {
		return
	}

	logging.ComponentEvent("router", "vector_store_init_started", map[string]interface{}{
		"backend": cfg.VectorStore.BackendType,
	})
	if err := cfg.VectorStore.Validate(); err != nil {
		logging.ComponentFatalEvent("router", "vector_store_config_invalid", map[string]interface{}{
			"backend": cfg.VectorStore.BackendType,
			"error":   err.Error(),
		})
	}
	vectorStoreRuntime, err := routerruntime.NewVectorStoreRuntime(cfg)
	if err != nil {
		logging.ComponentFatalEvent("router", "vector_store_runtime_create_failed", map[string]interface{}{
			"backend": cfg.VectorStore.BackendType,
			"error":   err.Error(),
		})
	}
	if runtimeRegistry != nil {
		runtimeRegistry.SetVectorStoreRuntime(vectorStoreRuntime)
	}
	vectorStoreRuntime.LogInitialized("router", cfg)
	registerVectorStoreShutdownHook(shutdownHooks, vectorStoreRuntime)
}

func registerVectorStoreShutdownHook(
	shutdownHooks *[]func(),
	vectorStoreRuntime *routerruntime.VectorStoreRuntime,
) {
	*shutdownHooks = append(*shutdownHooks, func() {
		logging.ComponentEvent("router", "vector_store_shutdown_started", map[string]interface{}{})
		if err := vectorStoreRuntime.Shutdown(); err != nil {
			logging.ComponentErrorEvent("router", "vector_store_shutdown_failed", map[string]interface{}{
				"error": err.Error(),
			})
		}
	})
}

func newExtProcServerOrFatal(
	opts runtimeOptions,
	writer startupstatus.StatusWriter,
	runtimeRegistry *routerruntime.Registry,
) *extproc.Server {
	server, err := extproc.NewServer(opts.configPath, opts.port, opts.secure, opts.certPath, runtimeRegistry)
	if err != nil {
		failStartup(writer, "Failed to create ExtProc server: %v", err)
	}

	return server
}

func warmupRouterRuntime(server *extproc.Server, embeddingState modelruntime.EmbeddingRuntimeState) {
	router := server.GetRouter()
	if router == nil {
		return
	}
	_, _ = modelruntime.WarmupRouter(context.Background(), []modelruntime.RouterWarmupTask{
		{
			Name:       "tools_database",
			Ready:      embeddingState.ToolsReady,
			SkipReason: "embedding_runtime_not_ready_for_tools",
			Load:       router.LoadToolsDatabase,
		},
		{
			Name:       "knowledge_bases",
			Ready:      embeddingState.AnyReady,
			SkipReason: "embedding_runtime_not_ready_for_knowledge_bases",
			Load:       router.PreloadKnowledgeBases,
		},
	}, modelruntime.WarmupRouterOptions{
		Component:      "router",
		MaxParallelism: 2,
		OnEvent:        logRuntimeLifecycleEvent,
	})
}

func startAPIServerIfEnabled(opts runtimeOptions, runtimeRegistry *routerruntime.Registry) {
	if !opts.enableAPI {
		return
	}

	go func() {
		logging.ComponentEvent("router", "api_server_starting", map[string]interface{}{
			"api_port":                   opts.apiPort,
			"api_bind":                   opts.apiBind,
			"management_auth_mode":       opts.managementAuthMode,
			"management_remote_exposure": opts.managementRemoteExpose,
		})
		if err := apiserver.InitWithOptions(apiserver.InitOptions{
			ConfigPath:      opts.configPath,
			Port:            opts.apiPort,
			BindAddress:     opts.apiBind,
			RemoteExposure:  opts.managementRemoteExpose,
			AuthMode:        opts.managementAuthMode,
			RuntimeRegistry: runtimeRegistry,
		}); err != nil {
			logging.ComponentErrorEvent("router", "api_server_failed", map[string]interface{}{
				"api_port": opts.apiPort,
				"error":    err.Error(),
			})
		}
	}()
}

func markRouterReady(writer startupstatus.StatusWriter, embeddingProvider *startupstatus.EmbeddingProviderStatus) {
	writeStartupState(writer, startupstatus.State{
		Phase:             "ready",
		Ready:             true,
		Message:           "Router models are ready. Starting router services...",
		EmbeddingProvider: embeddingProvider,
	}, "Failed to write ready startup status")
}

func startKubernetesControllerIfNeeded(cfg *config.RouterConfig, kubeconfig, namespace string) {
	if cfg.ConfigSource == config.ConfigSourceKubernetes {
		go startKubernetesController(cfg, kubeconfig, namespace)
	}
}

func startExtProcServerOrFatal(server *extproc.Server, writer startupstatus.StatusWriter) {
	if err := server.Start(); err != nil {
		failStartup(writer, "ExtProc server error: %v", err)
	}
}

package metrics

import (
	"sync"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/promauto"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/consts"
)

// Default time windows for windowed metrics
var DefaultTimeWindows = []string{"1m", "5m", "15m", "1h", "24h"}

// Default update interval for computing windowed metrics
const DefaultUpdateInterval = 10 * time.Second

// Default maximum models to track
const DefaultMaxModels = 100

// WindowedMetricsManager manages time-windowed metrics for load balancing
type WindowedMetricsManager struct {
	config         config.WindowedMetricsConfig
	timeWindows    []time.Duration
	windowLabels   []string
	updateInterval time.Duration
	maxModels      int

	// Ring buffers for storing request data per model
	requestBuffers map[string]*RequestRingBuffer
	bufferMutex    sync.RWMutex

	// Active request tracking for queue depth estimation
	activeRequests map[string]int64
	activeMutex    sync.RWMutex

	// Stop channel for background goroutine
	stopChan chan struct{}
	running  bool
}

// RequestData represents a single request's data for windowed tracking
type RequestData struct {
	Timestamp        time.Time
	Model            string
	LatencySeconds   float64
	PromptTokens     int64
	CompletionTokens int64
	IsError          bool
	IsTimeout        bool
}

// RequestRingBuffer is a time-based ring buffer for storing request data
type RequestRingBuffer struct {
	data     []RequestData
	head     int
	size     int
	capacity int
	mutex    sync.RWMutex
}

// NewRequestRingBuffer creates a new ring buffer with the given capacity
func NewRequestRingBuffer(capacity int) *RequestRingBuffer {
	return &RequestRingBuffer{
		data:     make([]RequestData, capacity),
		capacity: capacity,
	}
}

// Add adds a request to the ring buffer
func (rb *RequestRingBuffer) Add(req RequestData) {
	rb.mutex.Lock()
	defer rb.mutex.Unlock()

	rb.data[rb.head] = req
	rb.head = (rb.head + 1) % rb.capacity
	if rb.size < rb.capacity {
		rb.size++
	}
}

// GetDataSince returns all request data since the given time
func (rb *RequestRingBuffer) GetDataSince(since time.Time) []RequestData {
	rb.mutex.RLock()
	defer rb.mutex.RUnlock()

	result := make([]RequestData, 0, rb.size)
	for i := 0; i < rb.size; i++ {
		idx := (rb.head - rb.size + i + rb.capacity) % rb.capacity
		if !rb.data[idx].Timestamp.Before(since) {
			result = append(result, rb.data[idx])
		}
	}
	return result
}

// Prometheus metrics for windowed model tracking
var (
	// ModelLatencyWindowed tracks latency by model and time window
	ModelLatencyWindowed *prometheus.GaugeVec

	// ModelRequestsWindowed tracks request counts by model and time window
	ModelRequestsWindowed *prometheus.GaugeVec

	// ModelTokensWindowed tracks token throughput by model, token type, and time window
	ModelTokensWindowed *prometheus.GaugeVec

	// ModelUtilization tracks utilization percentage by model and time window
	ModelUtilization *prometheus.GaugeVec

	// ModelQueueDepth tracks estimated queue depth by model
	ModelQueueDepth *prometheus.GaugeVec

	// ModelErrorRate tracks error rate by model and time window
	ModelErrorRate *prometheus.GaugeVec

	// ModelLatencyP50 tracks P50 latency by model and time window
	ModelLatencyP50 *prometheus.GaugeVec

	// ModelLatencyP95 tracks P95 latency by model and time window
	ModelLatencyP95 *prometheus.GaugeVec

	// ModelLatencyP99 tracks P99 latency by model and time window
	ModelLatencyP99 *prometheus.GaugeVec

	windowedMetricsInitOnce sync.Once
)

// Global instance of WindowedMetricsManager
var (
	globalWindowedManager      *WindowedMetricsManager
	globalWindowedManagerMutex sync.RWMutex
)

// InitializeWindowedMetrics initializes the windowed metrics system
func InitializeWindowedMetrics(cfg config.WindowedMetricsConfig) error {
	windowedMetricsInitOnce.Do(func() {
		// Initialize Prometheus metrics
		ModelLatencyWindowed = promauto.NewGaugeVec(
			prometheus.GaugeOpts{
				Name: "llm_model_latency_windowed_seconds",
				Help: "Average latency by model and time window",
			},
			[]string{"model", "time_window"},
		)

		ModelRequestsWindowed = promauto.NewGaugeVec(
			prometheus.GaugeOpts{
				Name: "llm_model_requests_windowed_total",
				Help: "Total requests by model and time window",
			},
			[]string{"model", "time_window"},
		)

		ModelTokensWindowed = promauto.NewGaugeVec(
			prometheus.GaugeOpts{
				Name: "llm_model_tokens_windowed_total",
				Help: "Total tokens by model, token type, and time window",
			},
			[]string{"model", "token_type", "time_window"},
		)

		ModelUtilization = promauto.NewGaugeVec(
			prometheus.GaugeOpts{
				Name: "llm_model_utilization_percentage",
				Help: "Estimated utilization percentage by model and time window",
			},
			[]string{"model", "time_window"},
		)

		ModelQueueDepth = promauto.NewGaugeVec(
			prometheus.GaugeOpts{
				Name: "llm_model_queue_depth_estimated",
				Help: "Estimated queue depth by model",
			},
			[]string{"model"},
		)

		ModelErrorRate = promauto.NewGaugeVec(
			prometheus.GaugeOpts{
				Name: "llm_model_error_rate_windowed",
				Help: "Error rate by model and time window",
			},
			[]string{"model", "time_window"},
		)

		ModelLatencyP50 = promauto.NewGaugeVec(
			prometheus.GaugeOpts{
				Name: "llm_model_latency_p50_windowed_seconds",
				Help: "P50 latency by model and time window",
			},
			[]string{"model", "time_window"},
		)

		ModelLatencyP95 = promauto.NewGaugeVec(
			prometheus.GaugeOpts{
				Name: "llm_model_latency_p95_windowed_seconds",
				Help: "P95 latency by model and time window",
			},
			[]string{"model", "time_window"},
		)

		ModelLatencyP99 = promauto.NewGaugeVec(
			prometheus.GaugeOpts{
				Name: "llm_model_latency_p99_windowed_seconds",
				Help: "P99 latency by model and time window",
			},
			[]string{"model", "time_window"},
		)
	})

	// Create and start the manager
	manager, err := NewWindowedMetricsManager(cfg)
	if err != nil {
		return err
	}

	globalWindowedManagerMutex.Lock()
	globalWindowedManager = manager
	globalWindowedManagerMutex.Unlock()

	manager.Start()
	return nil
}

// NewWindowedMetricsManager creates a new WindowedMetricsManager
func NewWindowedMetricsManager(cfg config.WindowedMetricsConfig) (*WindowedMetricsManager, error) {
	// Parse time windows
	windowStrings := cfg.TimeWindows
	if len(windowStrings) == 0 {
		windowStrings = DefaultTimeWindows
	}

	timeWindows := make([]time.Duration, 0, len(windowStrings))
	windowLabels := make([]string, 0, len(windowStrings))
	for _, ws := range windowStrings {
		d, parseErr := time.ParseDuration(ws)
		if parseErr != nil {
			// Skip invalid durations
			continue
		}
		timeWindows = append(timeWindows, d)
		windowLabels = append(windowLabels, ws)
	}

	// Parse update interval
	updateInterval := DefaultUpdateInterval
	if cfg.UpdateInterval != "" {
		if d, parseErr := time.ParseDuration(cfg.UpdateInterval); parseErr == nil {
			updateInterval = d
		}
	}

	// Set max models
	maxModels := cfg.MaxModels
	if maxModels <= 0 {
		maxModels = DefaultMaxModels
	}

	return &WindowedMetricsManager{
		config:         cfg,
		timeWindows:    timeWindows,
		windowLabels:   windowLabels,
		updateInterval: updateInterval,
		maxModels:      maxModels,
		requestBuffers: make(map[string]*RequestRingBuffer),
		activeRequests: make(map[string]int64),
		stopChan:       make(chan struct{}),
	}, nil
}

// Start begins the background metrics computation goroutine
func (m *WindowedMetricsManager) Start() {
	if m.running {
		return
	}
	m.running = true

	go func() {
		ticker := time.NewTicker(m.updateInterval)
		defer ticker.Stop()

		for {
			select {
			case <-ticker.C:
				m.computeWindowedMetrics()
			case <-m.stopChan:
				return
			}
		}
	}()
}

// Stop stops the background metrics computation
func (m *WindowedMetricsManager) Stop() {
	if !m.running {
		return
	}
	close(m.stopChan)
	m.running = false
}

// RecordRequest records a request for windowed metrics tracking
func (m *WindowedMetricsManager) RecordRequest(req RequestData) {
	if !m.config.Enabled {
		return
	}

	key := req.Model

	m.bufferMutex.Lock()
	buffer, exists := m.requestBuffers[key]
	if !exists {
		// Check if we've hit max models
		if len(m.requestBuffers) >= m.maxModels {
			m.bufferMutex.Unlock()
			return
		}
		buffer = NewRequestRingBuffer(10000) // Adjust capacity as needed
		m.requestBuffers[key] = buffer
	}
	m.bufferMutex.Unlock()

	buffer.Add(req)
}

// IncrementActiveRequests increments the active request count for queue depth tracking
func (m *WindowedMetricsManager) IncrementActiveRequests(model string) {
	if !m.config.QueueDepthEstimation {
		return
	}

	key := model

	m.activeMutex.Lock()
	m.activeRequests[key]++
	count := m.activeRequests[key]
	m.activeMutex.Unlock()

	// Update the gauge immediately (only if metrics are initialized)
	if ModelQueueDepth == nil {
		return
	}
	if model == "" {
		model = consts.UnknownLabel
	}
	ModelQueueDepth.WithLabelValues(model).Set(float64(count))
}

// DecrementActiveRequests decrements the active request count
func (m *WindowedMetricsManager) DecrementActiveRequests(model string) {
	if !m.config.QueueDepthEstimation {
		return
	}

	key := model

	m.activeMutex.Lock()
	m.activeRequests[key]--
	if m.activeRequests[key] < 0 {
		m.activeRequests[key] = 0
	}
	count := m.activeRequests[key]
	m.activeMutex.Unlock()

	// Update the gauge immediately (only if metrics are initialized)
	if ModelQueueDepth == nil {
		return
	}
	if model == "" {
		model = consts.UnknownLabel
	}
	ModelQueueDepth.WithLabelValues(model).Set(float64(count))
}

// computeWindowedMetrics computes all windowed metrics
func (m *WindowedMetricsManager) computeWindowedMetrics() {
	now := time.Now()

	m.bufferMutex.RLock()
	buffers := make(map[string]*RequestRingBuffer, len(m.requestBuffers))
	for k, v := range m.requestBuffers {
		buffers[k] = v
	}
	m.bufferMutex.RUnlock()

	// Compute metrics for each model and each time window
	for model, buffer := range buffers {
		if model == "" {
			model = consts.UnknownLabel
		}

		for i, window := range m.timeWindows {
			windowLabel := m.windowLabels[i]
			since := now.Add(-window)
			data := buffer.GetDataSince(since)

			if len(data) == 0 {
				// Set zero values for empty windows
				ModelRequestsWindowed.WithLabelValues(model, windowLabel).Set(0)
				ModelLatencyWindowed.WithLabelValues(model, windowLabel).Set(0)
				ModelErrorRate.WithLabelValues(model, windowLabel).Set(0)
				continue
			}

			// Compute metrics
			var totalLatency float64
			var totalPromptTokens, totalCompletionTokens int64
			var errorCount int
			latencies := make([]float64, 0, len(data))

			for _, d := range data {
				totalLatency += d.LatencySeconds
				totalPromptTokens += d.PromptTokens
				totalCompletionTokens += d.CompletionTokens
				latencies = append(latencies, d.LatencySeconds)
				if d.IsError || d.IsTimeout {
					errorCount++
				}
			}

			requestCount := float64(len(data))
			avgLatency := totalLatency / requestCount
			errorRate := float64(errorCount) / requestCount

			// Update Prometheus metrics
			ModelRequestsWindowed.WithLabelValues(model, windowLabel).Set(requestCount)
			ModelLatencyWindowed.WithLabelValues(model, windowLabel).Set(avgLatency)
			ModelTokensWindowed.WithLabelValues(model, "prompt", windowLabel).Set(float64(totalPromptTokens))
			ModelTokensWindowed.WithLabelValues(model, "completion", windowLabel).Set(float64(totalCompletionTokens))
			ModelErrorRate.WithLabelValues(model, windowLabel).Set(errorRate)

			// Compute percentiles
			if len(latencies) > 0 {
				p50 := computePercentile(latencies, 0.50)
				p95 := computePercentile(latencies, 0.95)
				p99 := computePercentile(latencies, 0.99)

				ModelLatencyP50.WithLabelValues(model, windowLabel).Set(p50)
				ModelLatencyP95.WithLabelValues(model, windowLabel).Set(p95)
				ModelLatencyP99.WithLabelValues(model, windowLabel).Set(p99)
			}

			// Compute utilization (requests per second / expected capacity)
			// This is a simple approximation based on request rate
			requestsPerSecond := requestCount / window.Seconds()
			// Assume 100 req/s as theoretical max for utilization calculation
			// This can be made configurable
			utilization := (requestsPerSecond / 100.0) * 100.0
			if utilization > 100.0 {
				utilization = 100.0
			}
			ModelUtilization.WithLabelValues(model, windowLabel).Set(utilization)
		}
	}
}

// computePercentile computes the given percentile from a slice of values
func computePercentile(values []float64, percentile float64) float64 {
	if len(values) == 0 {
		return 0
	}

	// Sort the values
	sorted := make([]float64, len(values))
	copy(sorted, values)
	sortFloat64s(sorted)

	// Calculate the index
	index := percentile * float64(len(sorted)-1)
	lower := int(index)
	upper := lower + 1

	if upper >= len(sorted) {
		return sorted[len(sorted)-1]
	}

	// Linear interpolation
	weight := index - float64(lower)
	return sorted[lower]*(1-weight) + sorted[upper]*weight
}

// sortFloat64s sorts a slice of float64 in ascending order
func sortFloat64s(a []float64) {
	// Simple insertion sort for small slices, quick sort for larger
	if len(a) < 12 {
		for i := 1; i < len(a); i++ {
			for j := i; j > 0 && a[j] < a[j-1]; j-- {
				a[j], a[j-1] = a[j-1], a[j]
			}
		}
		return
	}

	// Quick sort
	quickSort(a, 0, len(a)-1)
}

func quickSort(a []float64, low, high int) {
	if low < high {
		p := partition(a, low, high)
		quickSort(a, low, p-1)
		quickSort(a, p+1, high)
	}
}

func partition(a []float64, low, high int) int {
	pivot := a[high]
	i := low - 1
	for j := low; j < high; j++ {
		if a[j] <= pivot {
			i++
			a[i], a[j] = a[j], a[i]
		}
	}
	a[i+1], a[high] = a[high], a[i+1]
	return i + 1
}

// Global helper functions for recording windowed metrics

// RecordModelWindowedRequest records a request to the global windowed metrics manager
func RecordModelWindowedRequest(model string, latencySeconds float64, promptTokens, completionTokens int64, isError, isTimeout bool) {
	globalWindowedManagerMutex.RLock()
	manager := globalWindowedManager
	globalWindowedManagerMutex.RUnlock()

	if manager == nil {
		return
	}

	manager.RecordRequest(RequestData{
		Timestamp:        time.Now(),
		Model:            model,
		LatencySeconds:   latencySeconds,
		PromptTokens:     promptTokens,
		CompletionTokens: completionTokens,
		IsError:          isError,
		IsTimeout:        isTimeout,
	})
}

// IncrementModelActiveRequests increments the active request count
func IncrementModelActiveRequests(model string) {
	globalWindowedManagerMutex.RLock()
	manager := globalWindowedManager
	globalWindowedManagerMutex.RUnlock()

	if manager == nil {
		return
	}

	manager.IncrementActiveRequests(model)
}

// DecrementModelActiveRequests decrements the active request count
func DecrementModelActiveRequests(model string) {
	globalWindowedManagerMutex.RLock()
	manager := globalWindowedManager
	globalWindowedManagerMutex.RUnlock()

	if manager == nil {
		return
	}

	manager.DecrementActiveRequests(model)
}

// GetWindowedMetricsManager returns the global windowed metrics manager
func GetWindowedMetricsManager() *WindowedMetricsManager {
	globalWindowedManagerMutex.RLock()
	defer globalWindowedManagerMutex.RUnlock()
	return globalWindowedManager
}

// IsWindowedMetricsEnabled returns true if windowed metrics are enabled
func IsWindowedMetricsEnabled() bool {
	globalWindowedManagerMutex.RLock()
	manager := globalWindowedManager
	globalWindowedManagerMutex.RUnlock()

	return manager != nil && manager.config.Enabled
}

